#include <assert.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "uda-types.h"
#include "uda-defs.h"
#include "uda-plugin-config.h"
#include "uda-plugin-types.h"
#include "uda-plugin-defs.h"
#include "uda-plugin.h"
#include "uda-plugin-cb.h"
#include "uda-plugin-utils.h"

/* Callback vector, supplied by the UDA server.  */
const uda_basic_callbacks_t *callbacks = 0;

/* First entry point called from the UDA server.  Establish
   the callback vector and perform other initializations.  */

void
uda_setup_basic_callbacks (uda_basic_callbacks_t const *cb)
{
  callbacks = cb;
}

/* Versioning information. */
const char *
uda_version_string (void)
{
  return UDA_VERSION_STRING "; Compiled " __DATE__;
}

int
uda_version_compatibility (void)
{
  return UPCDA_INTERFACE_COMPATIBILITY;
}

/* Error code to string mapping.  */
const char *
uda_error_string (int err)
{
  return "unknown UPC Debug Assistant error";	/* No errors yet */
}
